Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=(), event=Decided(decision='sharedhunk', at=datetime(2026, 11, 6, 0, 0, 0), actor='assistant', title='A file every change edits is a conflict by construction: give each change its own file', body='When every pull request must edit the same lines of one file (a changelog section, a registry list, a pin), two pull requests in flight conflict by construction, and a train can only repair it after the fact. Give each change its own file instead, and make the shared file a reading: a fold of those files, written only by the step that owns it (the release, a generator).', rationale='2026-11-04 to 2026-11-06: changelog conflicts cost five trains in two days until #360 made each entry a fragment.', supersedes=()))